def insert_at_position(head, data, pos):
    if pos == 1 or head is None:
        return Node(data, head)
    cur = head
    for _ in range(pos - 2):
        if cur.next is None:
            break
        cur = cur.next
    cur.next = Node(data, cur.next)
    return head

